"use client";

import { useEffect, useRef, useState, type FormEvent } from "react";
import { ArrowRight, BookOpen, Check, CheckCircle2, Clock3, Film, Library, Menu, Play, Search, Sparkles, Tv, X, Bell, BookmarkPlus, Clapperboard, Smartphone, ListVideo, CircleCheck } from "lucide-react";

// Embedded poster artwork from the provided app screenshot. No public image files needed.
const visionquestPoster = "data:image/jpeg;base64,";
const worldTriggerPoster = "data:image/jpeg;base64,";
const darkMatterPoster = "data:image/jpeg;base64,";

const features = [
  { icon: Library, title: "Everything in one library", description: "Keep movies, TV series, anime, and manga together instead of juggling lists and notes." },
  { icon: Play, title: "Pick up where you left off", description: "Track episodes, chapters, volumes, and movie progress at your own pace." },
  { icon: Search, title: "Find it. Save it. Done.", description: "Discover titles and add them to your library in just a few clicks." },
  { icon: CheckCircle2, title: "Know what's next", description: "Organize titles into Watching, Watch Later, Completed, and On Hold." },
];

const perks = ["Movies, TV, anime & manga", "Personal watch and reading lists", "Episode and chapter tracking", "Progress and status updates", "Personal notes", "Free during early access"];

export default function WelcomePage() {
  const previewRef = useRef<HTMLDivElement>(null);
  const phoneRef = useRef<HTMLDivElement>(null);
  const animationFrames = useRef<{ dashboard: number | null; phone: number | null }>({ dashboard: null, phone: null });

  function moveShowcase(event: React.PointerEvent<HTMLElement>, target: "dashboard" | "phone") {
    if (event.pointerType === "touch" || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const element = target === "dashboard" ? previewRef.current : phoneRef.current;
    if (!element) return;
    const rect = event.currentTarget.getBoundingClientRect();
    const x = Math.max(-1, Math.min(1, ((event.clientX - rect.left) / rect.width - 0.5) * 2));
    const y = Math.max(-1, Math.min(1, ((event.clientY - rect.top) / rect.height - 0.5) * 2));
    if (animationFrames.current[target] !== null) cancelAnimationFrame(animationFrames.current[target]!);
    animationFrames.current[target] = requestAnimationFrame(() => {
      element.style.setProperty("--tilt-x", `${(-y * 12).toFixed(2)}deg`);
      element.style.setProperty("--tilt-y", `${(x * 14).toFixed(2)}deg`);
    });
  }

  function resetShowcase(target: "dashboard" | "phone") {
    if (animationFrames.current[target] !== null) cancelAnimationFrame(animationFrames.current[target]!);
    animationFrames.current[target] = null;
    const element = target === "dashboard" ? previewRef.current : phoneRef.current;
    element?.style.setProperty("--tilt-x", "0deg");
    element?.style.setProperty("--tilt-y", "0deg");
  }

  useEffect(() => () => {
    for (const frame of Object.values(animationFrames.current)) {
      if (frame !== null) cancelAnimationFrame(frame);
    }
  }, []);

  const [currentYear, setCurrentYear] = useState<number | null>(null);
  const [menuOpen, setMenuOpen] = useState(false);
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [website, setWebsite] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [status, setStatus] = useState<"idle" | "success" | "error">("idle");
  const [message, setMessage] = useState("");

  useEffect(() => {
    setCurrentYear(new Date().getFullYear());
  }, []);

  async function requestAccess(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (submitting) return;
    setSubmitting(true);
    setStatus("idle");
    setMessage("");
    try {
      const response = await fetch("/api/access-requests", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name: name.trim(), email: email.trim(), website }),
      });
      const data = (await response.json()) as { error?: string };
      if (!response.ok) throw new Error(data.error || "Could not send your request.");
      setStatus("success");
      setMessage("You're on the list! We'll be in touch about access.");
      setName("");
      setEmail("");
    } catch (error) {
      setStatus("error");
      setMessage(error instanceof Error ? error.message : "Please try again.");
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div className={"welcome-page"}>
      <header className={"welcome-header"}>
        <div className={"welcome-nav-inner"}>
          <a href="/welcome" className={"welcome-brand"} aria-label="MyMedia home"><span className={"welcome-brand-mark"}><Film size={21} /></span><span>MyMedia</span></a>
          <nav className={`welcome-nav-links ${menuOpen ? "welcome-nav-open" : ""}`} aria-label="Main navigation">
            <a href="#features" onClick={() => setMenuOpen(false)}>Features</a>
            <a href="#how-it-works" onClick={() => setMenuOpen(false)}>How It Works</a>
            <a href="#get-access" onClick={() => setMenuOpen(false)}>Get Access</a>
          </nav>
          <div className={"welcome-nav-actions"}><a className={"welcome-sign-in"} href="/login">Sign in</a><a className={"welcome-nav-cta"} href="#get-access">Request access <ArrowRight size={15}/></a></div>
          <button className={"welcome-menu-button"} aria-label={menuOpen ? "Close menu" : "Open menu"} aria-expanded={menuOpen} onClick={() => setMenuOpen(!menuOpen)}>{menuOpen ? <X size={23}/> : <Menu size={23}/>}</button>
        </div>
      </header>

      <main>
        <section className={"welcome-hero"} onPointerMove={(event) => moveShowcase(event, "dashboard")} onPointerLeave={() => resetShowcase("dashboard")}>
          <div className={"welcome-hero-glow"} aria-hidden="true" />
          <div className={"welcome-hero-inner"}>
            <div className={"welcome-hero-copy"}>
              <span className={"welcome-eyebrow"}><span className={"welcome-eyebrow-dot"}/> FREE EARLY ACCESS</span>
              <h1>Everything you want to watch.<br/><span>Nothing you want to miss.</span></h1>
              <p>Stop wasting time deciding what to watch. Save the movies, shows, anime, and manga you want to enjoy, keep track of your progress, and never lose a recommendation again.</p>
              <div className={"welcome-hero-actions"}><a className={"welcome-primary-button"} href="#get-access">Request free access <ArrowRight size={18}/></a><a className={"welcome-secondary-button"} href="#how-it-works">See how it works <Play size={16}/></a></div>
              <div className={"welcome-hero-foot"}><CheckCircle2 size={16}/> Free to use during early access <span>·</span> No credit card required</div>
            </div>
            <div className={"welcome-preview-wrap"} ref={previewRef} aria-label="Interactive preview of the MyMedia dashboard. Move your mouse to tilt the preview.">
              <div className="welcome-preview-window">
                <div className="welcome-real-dashboard">
                  <aside className="welcome-dash-sidebar">
                    <div className="welcome-dash-brand"><Film size={16}/> <strong>MyMedia</strong></div>
                    <div className="welcome-dash-nav"><span className="is-active"><Library size={14}/> Dashboard</span><span><Search size={14}/> Discover</span><span><ListVideo size={14}/> My Library</span></div>
                    <div className="welcome-dash-sidebar-bottom"><span className="welcome-dash-avatar">M</span> My Library</div>
                  </aside>
                  <div className="welcome-dash-main">
                    <div className="welcome-dash-toolbar"><div><h3>My Dashboard</h3><p>Your media collection at a glance.</p></div><span className="welcome-dash-search"><Search size={12}/> Search movies, anime, TV...</span></div>
                    <div className="welcome-dash-stats">
                      <div><span className="purple"><Library size={14}/></span><div><small>Total Titles</small><strong>32</strong></div></div>
                      <div><span className="blue"><Play size={14}/></span><div><small>Watching</small><strong>8</strong></div></div>
                      <div><span className="green"><CircleCheck size={14}/></span><div><small>Completed</small><strong>12</strong></div></div>
                      <div><span className="orange"><Clock3 size={14}/></span><div><small>Watch Later</small><strong>12</strong></div></div>
                    </div>
                    <div className="welcome-dash-section"><div className="welcome-dash-section-title"><strong>Continue Watching</strong><span>View all →</span></div>
                      <div className="welcome-dash-posters">
                        <div className="welcome-dash-poster-item"><div className="welcome-dash-poster"><img src="https://image.tmdb.org/t/p/w500/gEU2QniE6E77NI6lCU6MxlNBvIx.jpg" alt="Interstellar movie poster"/><span>Movie</span></div><strong>Interstellar</strong><small>Watching</small><div className="welcome-dash-progress"><i style={{width:"62%"}}/></div></div>
                        <div className="welcome-dash-poster-item"><div className="welcome-dash-poster"><img src="https://image.tmdb.org/t/p/w500/39wmItIWsg5sZMyRUHLkWBcuVCM.jpg" alt="Spirited Away movie poster"/><span>Anime</span></div><strong>Spirited Away</strong><small>Completed</small><div className="welcome-dash-progress"><i style={{width:"100%"}}/></div></div>
                        <div className="welcome-dash-poster-item"><div className="welcome-dash-poster"><img src="https://image.tmdb.org/t/p/w500/1pdfLvkbY9ohJlCjQH2CZjjYVvJ.jpg" alt="Dune Part Two movie poster"/><span>Movie</span></div><strong>Dune: Part Two</strong><small>Watch Later</small><div className="welcome-dash-progress"><i style={{width:"8%"}}/></div></div>
                         <div className="welcome-dash-poster-item"><div className="welcome-dash-poster"><img src="https://image.tmdb.org/t/p/w500/qJ2tW6WMUDux911r6m7haRef0WH.jpg" alt="The Dark Knight movie poster" loading="lazy"/><span>Movie</span></div><strong>The Dark Knight</strong><small>Completed</small><div className="welcome-dash-progress"><i style={{width:"100%"}}/></div></div>
                         <div className="welcome-dash-poster-item"><div className="welcome-dash-poster"><img src="https://image.tmdb.org/t/p/w500/oYuLEt3zVCKq57qu2F8dT7NIa6f.jpg" alt="Inception movie poster" loading="lazy"/><span>Movie</span></div><strong>Inception</strong><small>Watch Later</small><div className="welcome-dash-progress"><i style={{width:"0%"}}/></div></div>
                         <div className="welcome-dash-poster-item"><div className="welcome-dash-poster"><img src="https://image.tmdb.org/t/p/w500/q719jXXEzOoYaps6babgKnONONX.jpg" alt="Your Name anime poster" loading="lazy"/><span>Anime</span></div><strong>Your Name</strong><small>Completed</small><div className="welcome-dash-progress"><i style={{width:"100%"}}/></div></div>
                         <div className="welcome-dash-poster-item"><div className="welcome-dash-poster"><img src="https://image.tmdb.org/t/p/w500/3xnWaLQjelJDDF7LT1WBo6f4BRe.jpg" alt="Breaking Bad television poster" loading="lazy"/><span>TV</span></div><strong>Breaking Bad</strong><small>Watching</small><div className="welcome-dash-progress"><i style={{width:"45%"}}/></div></div>

                      </div>
                    </div>
                  </div>
                </div>
              </div>
              <div className={"welcome-float-note"}><span><BookOpen size={18}/></span><div><strong>Your progress, in one place</strong><small>Pick up whenever you’re ready.</small></div><CheckCircle2 size={18}/></div>
            </div>
          </div>
        </section>

        <section className={"welcome-trust-strip"}><span>YOUR ENTERTAINMENT, ORGANIZED</span><div><span><Film size={18}/> Movies</span><span><Tv size={18}/> TV Series</span><span><Sparkles size={18}/> Anime</span><span><BookOpen size={18}/> Manga</span></div></section>

        <section className="welcome-pain-section" aria-labelledby="welcome-pain-heading">
          <div className="welcome-section-intro">
            <span className="welcome-kicker">SOUND FAMILIAR?</span>
            <h2 id="welcome-pain-heading">No more <span>“what was I going to watch?”</span></h2>
            <p>Less time searching, remembering, and checking release dates. More time enjoying what you love.</p>
          </div>
          <div className="welcome-pain-grid">
            <article className="welcome-pain-card">
              <span className="welcome-pain-icon"><Clapperboard size={24}/></span>
              <span className="welcome-pain-number">01 / DECIDE FASTER</span>
              <h3>No more spending 10 minutes figuring out what to watch.</h3>
              <p>Keep your watchlist in one place so your next pick is already waiting for you.</p>
              <div className="welcome-pain-example"><span className="welcome-example-dot"/> Your Watch Later list <strong>Ready when you are</strong></div>
            </article>
            <article className="welcome-pain-card">
              <span className="welcome-pain-icon"><Bell size={24}/></span>
              <span className="welcome-pain-number">02 / STAY IN THE LOOP</span>
              <h3>No more missing release dates.</h3>
              <p>Follow upcoming episodes, premieres, and releases without constantly checking for updates.</p>
              <div className="welcome-pain-example"><span className="welcome-example-dot welcome-example-dot-amber"/> Release alerts <strong>Coming soon</strong></div>
            </article>
            <article className="welcome-pain-card">
              <span className="welcome-pain-icon"><BookmarkPlus size={24}/></span>
              <span className="welcome-pain-number">03 / NEVER FORGET</span>
              <h3>No more forgetting what you wanted to watch later.</h3>
              <p>Save that recommendation or interesting title as soon as you discover it.</p>
              <div className="welcome-pain-example"><span className="welcome-example-dot"/> Saved to your library <strong>Watch Later</strong></div>
            </article>
          </div>
        </section>

        <section id="features" className={"welcome-section"}><div className={"welcome-section-intro"}><span className={"welcome-kicker"}>BUILT FOR YOUR BACKLOG</span><h2>Everything you love.<br/><span>One organized library.</span></h2><p>Find your next pick, keep track of where you left off, and save the stories you want to return to.</p></div><div className={"welcome-feature-grid"}>{features.map(({ icon: Icon, title, description }) => <article key={title} className={"welcome-feature-card"}><span className={"welcome-feature-icon"}><Icon size={23}/></span><h3>{title}</h3><p>{description}</p></article>)}</div></section>

        <section className="welcome-mobile-section" aria-labelledby="welcome-mobile-heading" onPointerMove={(event) => moveShowcase(event, "phone")} onPointerLeave={() => resetShowcase("phone")}>
          <div className="welcome-mobile-inner">
            <div className="welcome-mobile-visual" ref={phoneRef}>
              <div className="welcome-phone" aria-label="Preview of the actual MyMedia mobile dashboard">
                <div className="welcome-phone-screen">
                  <div className="welcome-actual-top">
                    <div className="welcome-actual-heading">
                      <div><h3>Good evening!</h3><p>Here's what you're watching and reading.</p></div>
                      <span className="welcome-actual-avatar">W</span>
                    </div>
                    <div className="welcome-actual-stats">
                      <div className="welcome-actual-stat"><span className="welcome-actual-stat-icon purple"><Play size={18}/></span><div><small>Watching / Reading</small><strong>7</strong></div></div>
                      <div className="welcome-actual-stat"><span className="welcome-actual-stat-icon blue"><BookmarkPlus size={18}/></span><div><small>Watch Later</small><strong>4</strong></div></div>
                      <div className="welcome-actual-stat"><span className="welcome-actual-stat-icon green"><Check size={18}/></span><div><small>Completed</small><strong>15</strong></div></div>
                      <div className="welcome-actual-stat"><span className="welcome-actual-stat-icon amber"><Clock3 size={18}/></span><div><small>On Hold</small><strong>1</strong></div></div>
                    </div>
                  </div>
                  <div className="welcome-actual-media-heading"><strong>Continue Watching &amp; Reading</strong><span>See all ›</span></div>
                  <div className="welcome-actual-media-track">
                    <div className="welcome-actual-media-card"><div className="welcome-actual-poster"><img src={visionquestPoster} alt="VisionQuest series poster" /><span>Series</span></div><strong>VisionQuest</strong><small>S1 · E4</small></div>
                    <div className="welcome-actual-media-card"><div className="welcome-actual-poster"><img src={worldTriggerPoster} alt="World Trigger manga cover" /><span>Manga</span></div><strong>World Trigger</strong><small>Chapter 253</small></div>
                    <div className="welcome-actual-media-card"><div className="welcome-actual-poster"><img src={darkMatterPoster} alt="Dark Matter series poster" /><span>Series</span></div><strong>Dark Matter</strong><small>S2 · E7</small></div>
                  </div>
                  <div className="welcome-actual-tabbar">
                    <span className="active"><Library size={19}/>Home</span>
                    <span><BookOpen size={19}/>Library</span>
                    <span><Search size={19}/>Search</span>
                    <span><Menu size={19}/>More</span>
                  </div>
                </div>
              </div>
              <div className="welcome-mobile-floating"><CheckCircle2 size={17}/><span>Everything stays in sync with your library</span></div>
            </div>
            <div className="welcome-mobile-copy">
              <span className="welcome-kicker"><Smartphone size={16}/> MYMEDIA ON MOBILE</span>
              <h2>Your library goes <span>wherever you go.</span></h2>
              <p>Remember a recommendation on the go, check your Watch Later list, or update your progress from your phone. Your MyMedia library is right there in your mobile browser.</p>
              <div className="welcome-mobile-benefits"><div><CheckCircle2 size={18}/> Save titles whenever inspiration strikes</div><div><CheckCircle2 size={18}/> Keep your watchlist close at hand</div><div><CheckCircle2 size={18}/> Pick up from any screen</div></div>
              <a className="welcome-secondary-button" href="#get-access">Request early access <ArrowRight size={17}/></a>
            </div>
          </div>
        </section>

        <section id="how-it-works" className={"welcome-how-section"}><div className={"welcome-section-intro"}><span className={"welcome-kicker"}>SIMPLE BY DESIGN</span><h2>Make room for the good stuff.</h2><p>Three simple steps. No spreadsheets or complicated setup.</p></div><div className={"welcome-steps"}><div><span className={"welcome-step-number"}>01</span><h3>Find a title</h3><p>Search for a movie, show, anime, or manga you've started or want to explore.</p></div><div><span className={"welcome-step-number"}>02</span><h3>Add it to your library</h3><p>Choose where it belongs: Watching, Watch Later, Completed, or On Hold.</p></div><div><span className={"welcome-step-number"}>03</span><h3>Track as you go</h3><p>Update your progress and pick up right where you left off next time.</p></div></div></section>

        <section id="get-access" className={"welcome-access-section"}><div className={"welcome-access-intro"}><span className={"welcome-kicker"}>JOIN THE EARLY ACCESS</span><h2>Your next favorite is waiting.</h2><p>We're opening MyMedia to early users. Request an invite and spend less time searching and more time enjoying.</p></div><div className={"welcome-access-card"}><div className={"welcome-card-top"}><span className={"welcome-access-tag"}>EARLY ACCESS</span><h3>MyMedia Free</h3><p>Everything you need to keep your media organized.</p><div className={"welcome-price"}><strong>$0</strong><span>CAD · currently free</span></div></div><div className={"welcome-card-body"}><div className={"welcome-included"}>WHAT'S INCLUDED</div><ul>{perks.map((perk) => <li key={perk}><Check size={17}/>{perk}</li>)}</ul><form onSubmit={requestAccess} className={"welcome-form"}><label htmlFor="access-name">Your name</label><input id="access-name" autoComplete="name" maxLength={100} required value={name} onChange={(e) => setName(e.target.value)} placeholder="Your name"/><label htmlFor="access-email">Email address</label><input id="access-email" type="email" autoComplete="email" maxLength={254} required value={email} onChange={(e) => setEmail(e.target.value)} placeholder="you@example.com"/><div className={"welcome-honeypot"} aria-hidden="true"><label htmlFor="access-website">Website</label><input id="access-website" tabIndex={-1} autoComplete="off" value={website} onChange={(e) => setWebsite(e.target.value)}/></div><button className={"welcome-primary-button"} type="submit" disabled={submitting}>{submitting ? "Sending request…" : "Request free access"}<ArrowRight size={18}/></button>{status !== "idle" && <p role="status" className={status === "success" ? "welcome-success" : "welcome-error"}>{message}</p>}</form><p className={"welcome-card-fine-print"}>No payment required. Access is by invitation while we grow.</p></div></div></section>
      </main>
      <footer className={"welcome-footer"}><div><a href="/welcome" className={"welcome-brand"}><span className={"welcome-brand-mark"}><Film size={19}/></span><span>MyMedia</span></a><p>Your stories, your pace, your library.</p></div><div><a href="#features">Features</a><a href="#how-it-works">How It Works</a><a href="#get-access">Get Access</a><a href="/login">Sign in</a></div><small>© {currentYear ?? "2026"} MyMedia. All rights reserved.</small><small className="welcome-poster-credit">Poster imagery via TMDB. This product is not endorsed or certified by TMDB.</small></footer>
    </div>
  );
}
